using System.ComponentModel.DataAnnotations;
using System.ComponentModel.DataAnnotations.Schema;

namespace SKVI.Domain.Entities
{
    [Table("DailyStudyTasks")]
    public class DailyStudyTask
    {
        [Key]
        public Guid Id { get; set; } = Guid.NewGuid();

        public Guid PlanId { get; set; }

        public DateTime TaskDate { get; set; }

        // The task description/content generated by AI
        [Required]
        public string Content { get; set; } = string.Empty;

        public bool IsCompleted { get; set; } = false;

        // Feedback from the user after completing (e.g. "It was too hard", "I learned a lot")
        public string UserFeedback { get; set; } = string.Empty;

        // AI's advice/feedback based on the user's feedback
        public string AiAdvice { get; set; } = string.Empty;

        public DateTime CreatedAt { get; set; } = DateTime.UtcNow;

        [ForeignKey("PlanId")]
        public virtual UserStudyPlan Plan { get; set; }
    }
}
